// Deterministic PRNG: mulberry32 (seeded with workflow execution ID)
function mulberry32(seed) {
  return function() {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
}
const rng = mulberry32($json._execution_seed || 12345);
const data = $input.first().json;
const positioning = {};
(data.competitors || []).forEach(c => { positioning[c.name] = {market_share: rng() * 30, growth_rate: rng() * 20 - 5, sentiment: rng() * 2 - 1}; });
const pricing = (data.competitors || []).map(c => ({name: c.name, last_change: '2024-01-15', delta_pct: rng() * 10 - 5}));
const hiring = {};
(data.competitors || []).forEach(c => { hiring[c.name] = {open_positions: Math.floor(rng() * 50), velocity: rng() > 0.5 ? 'ACCELERATING' : 'STABLE'}; });
const alerts = (data.competitors || []).filter(c => rng() > 0.7).map(c => ({type: 'PRICING_CHANGE', competitor: c.name, severity: 'HIGH'}));
return [{json: {competitive_positioning: positioning, pricing_trends: pricing, hiring_velocity: hiring, strategic_alerts: alerts}}];
